pm.test("Export CSV contains Miocene", function () {
const csv = pm.response.text();
    const lines = csv.trim().split(/\r?\n/);

    const headers = lines[0].split(",");
    const idIndex = headers.indexOf("id");

    const row = lines.slice(1)
        .map(line => line.split(","))
        .find(values => values[idIndex] === "miocene");

    pm.expect(row).to.exist;
    pm.expect(row[headers.indexOf("name")]).to.eql("Miocene");
    pm.expect(row[headers.indexOf("rank")]).to.eql("Epoch");
    pm.expect(row[headers.indexOf("parent_id")]).to.eql("neogene");
    pm.expect(Number(row[headers.indexOf("begin_time_ma")])).to.eql(23.04);
    pm.expect(Number(row[headers.indexOf("begin_uncertainty_ma")])).to.eql(0.0);
    pm.expect(Number(row[headers.indexOf("end_time_ma")])).to.eql(5.333);
    pm.expect(Number(row[headers.indexOf("end_uncertainty_ma")])).to.eql(0.0);
    pm.expect(Number(row[headers.indexOf("rank_order")])).to.eql(5);
});

